SELECT COUNT(*)
  FROM wb_requirement
 WHERE workflow_id = #{workflowId}

SELECT COUNT(*)
  FROM wb_requirement r
 WHERE r.project_id = #{projectId}


    AND r.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'


    AND r.status = #{status}

SELECT 
  FROM wb_requirement r
  LEFT JOIN wb_workflow w ON w.id = r.workflow_id
 WHERE r.project_id = #{projectId}

    AND r.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'


    AND r.status = #{status}

 ORDER BY r.created_at DESC, r.id DESC
 LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE wb_requirement
   SET dsh_workspace_path = #{path},
       updated_at = #{now}
 WHERE id = #{id}

UPDATE wb_requirement
   SET title = #{title},
       description = #{description},
       revision = revision + 1,
       updated_at = #{now}
 WHERE id = #{id}
   AND revision = #{expected}

mapper.delete:
DELETE FROM wb_requirement
 WHERE id = #{id}
   AND revision = #{revision}

